import React, { useState } from "react";
import PetCard from "../../components/PetCard";  // Asumând că ai acest path corect

const mockPets = [
    {
        id: "1",
        name: "Rex",
        breed: "Husky",
        age: "2 years",
        image: "https://place-puppy.com/300x300",
    },
    {
        id: "2",
        name: "Luna",
        breed: "Siamese",
        age: "1 year",
        image: "https://placekitten.com/300",
    },
];

const AdopterDashboard = () => {
    const [search, setSearch] = useState("");
    const [filters, setFilters] = useState({
        type: "",
        age: "",
    });

    // Filtrare + căutare simplă
    const filteredPets = mockPets.filter(pet => {
        const matchSearch = pet.name.toLowerCase().includes(search.toLowerCase()) || pet.breed.toLowerCase().includes(search.toLowerCase());
        const matchType = filters.type ? (filters.type === "dog" ? pet.breed.toLowerCase().includes("dog") : filters.type === "cat" ? pet.breed.toLowerCase().includes("cat") : true) : true;
        // aici poți ajusta logica pe tip
        const matchAge = filters.age ? filters.age === "adult" ? pet.age.toLowerCase().includes("year") : true : true;
        return matchSearch && matchType && matchAge;
    });

    return (
        <div className="adopter-container">
            {/* ... restul codului tău rămâne neschimbat ... */}

            <div className="cards-container">
                {filteredPets.map(pet => (
                    <PetCard key={pet.id} pet={pet} />
                ))}
            </div>
        </div>
    );
};

export default AdopterDashboard;
